type GachaTutorialProps = {
  currentStep: number;
  closeTutorial: () => void;
  goToNextStep: () => void;
  goToPreviousStep: () => void;
};

const GachaTutorial = ({
  currentStep,
  closeTutorial,
  goToNextStep,
  goToPreviousStep,
}: GachaTutorialProps) => {
  const stepData = gachaTutorialSteps[currentStep];
  const [targetBounds, setTargetBounds] = useState<ElementBounds | null>(null);

  useScrollToTarget(stepData, setTargetBounds);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "ArrowLeft" && currentStep > 0) {
        goToPreviousStep();
      } else if (
        e.key === "ArrowRight" &&
        currentStep < gachaTutorialSteps.length - 1
      ) {
        goToNextStep();
      } else if (e.key === "Escape") {
        closeTutorial();
      }
    };
    window.addEventListener("keydown", handleKeyDown);

    return () => {
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [closeTutorial, currentStep, goToNextStep, goToPreviousStep]);

  return (
    <>
      <FocusTrap>
        <div>
          {/* Overlay */}
          <TutorialOverlay
            targetBounds={targetBounds}
            closeTutorial={closeTutorial}
          />
          <DialogueFrame
            goToNextStep={goToNextStep}
            goToPreviousStep={goToPreviousStep}
            closeTutorial={closeTutorial}
            // The first step should be an intro and does not count towards the progress number,
            // so this is 0-indexed.
            currentStep={currentStep}
            numTotalSteps={gachaTutorialSteps.length - 1}
            afterCb={stepData.afterCb}
            prevCb={stepData.prevCb}
          >
            {stepData?.content}
          </DialogueFrame>
        </div>
      </FocusTrap>
    </>
  );
};

type GachaTutorialEntrypointProps = {
  queryParams?: ParsedQs | URLSearchParams;
  entrypoint?: (startTutorial: () => void) => React.ReactNode;
};

const GachaTutorialEntrypoint = ({
  queryParams,
  entrypoint,
}: GachaTutorialEntrypointProps) => {
  const {
    isTutorialOpen,
    currentStep,
    startTutorial,
    closeTutorial,
    goToNextStep,
    goToPreviousStep,
  } = useTutorial(gachaTutorialSteps, queryParams);

  useEffect(() => {
    if (localStorage.getItem(GACHA_TUTORIAL_STORAGE_KEY) === "true") {
      return;
    }
    localStorage.setItem(GACHA_TUTORIAL_STORAGE_KEY, "true");
    startTutorial();
  }, [startTutorial]);

  useEffect(() => {
    /**
     * Lock scrolling so that people can't scroll away from the highlighted item.
     */
    if (!isTutorialOpen) return;

    const originalOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";

    return () => {
      document.body.style.overflow = originalOverflow;
    };
  }, [isTutorialOpen]);

  return (
    <>
      {/* Entrypoint to tutorial. */}
      {entrypoint?.(startTutorial)}
      {isTutorialOpen && (
        <GachaTutorial
          currentStep={currentStep}
          closeTutorial={closeTutorial}
          goToNextStep={goToNextStep}
          goToPreviousStep={goToPreviousStep}
        />
      )}
    </>
  );
};

export default GachaTutorialEntrypoint;
