import { cn } from "@hunt/styled-ui";
import React from "react";
import { GachaActionButton } from "../components/GachaActionButton";

const ARROW_STYLING = `pt-1 pb-2 px-3 font-mono text-4xl leading-6 text-black rounded
transition-transform duration-150 ease-out select-none pointer-events-none
hover:scale-125 hover:text-cash-red
focus-visible:scale-125 focus-visible:text-cash-red origin-center`;

type DialogueFrameProps = {
  children: React.ReactNode;
  className?: string;
  goToPreviousStep: () => void;
  goToNextStep: () => void;
  closeTutorial: () => void;
  currentStep: number;
  numTotalSteps: number;
  afterCb?: () => void;
  prevCb?: () => void;
};

const DialogueFrame = ({
  children,
  className,
  goToNextStep,
  goToPreviousStep,
  closeTutorial,
  currentStep,
  numTotalSteps,
  afterCb,
  prevCb,
}: DialogueFrameProps) => {
  return (
    <div
      role="dialog"
      aria-modal="true"
      className="fixed bottom-12 left-0 right-0 z-[10001] flex justify-center text-black select-none"
    >
      <div
        id="tutorial-dialogue"
        className={cn(
          "relative w-[95%] max-w-5xl bg-white border-[6px] border-black rounded-3xl p-6 font-body text-xl leading-relaxed",
          className,
        )}
      >
        {/* Actual content */}
        <div className="whitespace-pre-line">{children}</div>

        {/* Navigation buttons */}
        <div className="mt-4 flex items-center justify-between pointer-events-auto">
          <div>
            {/* Invisible overlay */}
            {currentStep > 0 && (
              <button
                className="absolute top-0 left-0 w-1/2 h-full cursor-pointer z-30 peer/left focus-visible:outline-none"
                onClick={() => {
                  goToPreviousStep();
                  prevCb?.();
                }}
                tabIndex={-1}
              />
            )}
            {/* Left navigation button */}
            {currentStep === 0 ? (
              <p className="text-base text-neutral-500">
                (Click the arrow or use the arrow keys to proceed.)
              </p>
            ) : (
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  goToPreviousStep();
                  prevCb?.();
                }}
                className={cn(
                  ARROW_STYLING,
                  "peer-hover/left:scale-125 peer-hover/left:text-cash-red",
                )}
              >
                ◀
              </button>
            )}
          </div>

          {/* Pagination */}
          {currentStep > 0 && (
            <p className="absolute bottom-5 left-1/2 -translate-x-1/2 text-base text-neutral-500">
              {`${currentStep} / ${numTotalSteps}`}
            </p>
          )}

          <div>
            {/* Invisible overlay */}
            {currentStep < numTotalSteps && (
              <button
                className="absolute top-0 right-0 w-1/2 h-full cursor-pointer z-30 peer/right focus-visible:outline-none"
                onClick={() => {
                  goToNextStep();
                  afterCb?.();
                }}
                tabIndex={-1}
              />
            )}
            {/* Right navigation button */}
            {currentStep === numTotalSteps ? (
              <GachaActionButton
                variant="green"
                onClick={closeTutorial}
                className="font-normal"
              >
                Start pulling!
              </GachaActionButton>
            ) : (
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  goToNextStep();
                  afterCb?.();
                }}
                className={cn(
                  ARROW_STYLING,
                  "peer-hover/right:scale-125 peer-hover/right:text-cash-red",
                )}
              >
                ▶
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default DialogueFrame;
