import { cn } from "@hunt/styled-ui";
import { X } from "lucide-react";
import React from "react";

export type ElementBounds = {
  x: number;
  y: number;
  width: number;
  height: number;
};

type TutorialOverlayProps = {
  targetBounds: ElementBounds | null;
  closeTutorial: () => void;
};

const TutorialOverlay = ({
  targetBounds,
  closeTutorial,
}: TutorialOverlayProps) => {
  const { x, y, width, height } = targetBounds ?? {};

  return (
    <>
      <div
        aria-hidden="true"
        // The box-shadow creates the darkened overlay.
        className={cn(
          "fixed inset-0 z-[10000] pointer-events-none rounded-lg shadow-[0_0_0_9999px_rgba(0,0,0,0.7)]",
          targetBounds && "border-4 border-cash-red",
        )}
        style={{
          top: y ?? 0,
          left: x ?? 0,
          width: width ?? 0,
          height: height ?? 0,
        }}
      />
      {/* Close button in top-right of overlay */}
      <button
        onClick={closeTutorial}
        className="fixed top-4 right-4 z-[10002] bg-white border-2 border-black
                   rounded-full w-10 h-10 flex items-center justify-center text-black
                   hover:bg-red-500 hover:text-white transition-transform duration-150
                   ease-out focus-visible:scale-125 hover:scale-125 origin-center"
        aria-label="Close tutorial"
      >
        <X strokeWidth={2.5} />
      </button>
    </>
  );
};

export default TutorialOverlay;
