import { useEffect } from "react";
import { type ElementBounds } from "./TutorialOverlay";
import { type TutorialStep } from "./useTutorial";

export const useScrollToTarget = (
  stepData: TutorialStep,
  setTargetBounds: (bounds: ElementBounds | null) => void,
) => {
  /**
   * This entire function was vibe-coded, thanks ChatGPT.
   *
   * This function detects where the target element is and scrolls so that it is
   * within the bounds of the visible screen. We also avoid overlapping
   * with the dialogue box and X icon.
   */
  useEffect(() => {
    const TOP_BUFFER = 12;
    const EXTRA_TOP_BUFFER = 32;
    const TOP_RIGHT_BUFFER = 72;
    const BUFFER_FROM_DIALOGUE_BOX = 16;
    const PADDING = 8;

    const updateBounds = () => {
      const dialogueEl = document.getElementById("tutorial-dialogue");

      const hContainer = stepData.horizontalScrollContainerId
        ? document.getElementById(stepData.horizontalScrollContainerId)
        : window;
      const vContainer = stepData.verticalScrollContainerId
        ? document.getElementById(stepData.verticalScrollContainerId)
        : window;

      if (!stepData.selector) {
        // Scroll to top of page if there is no selector.
        if (vContainer === window) {
          window.scrollTo({ top: 0, behavior: "smooth" });
        } else {
          (vContainer as HTMLElement).scrollTo({
            top: 0,
            behavior: "smooth",
          });
        }
        setTargetBounds(null);
        return;
      }

      const el = document.querySelector(
        stepData.selector,
      ) as HTMLElement | null;

      if (!el || !dialogueEl || !hContainer || !vContainer) {
        setTargetBounds(null);
        return;
      }

      // current scroll positions
      const scrollTop =
        vContainer === window
          ? window.scrollY
          : (vContainer as HTMLElement).scrollTop;
      const scrollLeft =
        hContainer === window
          ? window.scrollX
          : (hContainer as HTMLElement).scrollLeft;

      const viewportHeight =
        vContainer === window
          ? window.innerHeight
          : (vContainer as HTMLElement).clientHeight;
      const viewportWidth =
        hContainer === window
          ? window.innerWidth
          : (hContainer as HTMLElement).clientWidth;

      const targetRect = el.getBoundingClientRect();
      const dialogueRect = dialogueEl.getBoundingClientRect();

      let topBound = TOP_BUFFER;
      // These are the bounds for the top left corner of the target rectangle.
      const bottomBound =
        viewportHeight -
        dialogueRect.height -
        48 -
        targetRect.height -
        BUFFER_FROM_DIALOGUE_BOX;
      if (topBound + EXTRA_TOP_BUFFER < bottomBound) {
        topBound += EXTRA_TOP_BUFFER;
      }
      const leftBound = TOP_BUFFER;
      const rightBound = viewportWidth - targetRect.width - TOP_BUFFER;

      // Determine the point within the bounds that is closest to the target's current top left corner.
      let desiredX = Math.max(Math.min(targetRect.left, rightBound), leftBound);
      let desiredY = Math.max(Math.min(targetRect.top, bottomBound), topBound);

      // We do not want to scroll such that the target ends up in the top right corner
      // because the X button is there.
      if (
        desiredX + targetRect.width > viewportWidth - TOP_RIGHT_BUFFER &&
        desiredY < TOP_RIGHT_BUFFER
      ) {
        desiredX = TOP_RIGHT_BUFFER - targetRect.width;
        desiredY = TOP_RIGHT_BUFFER;
      }

      // Determine the window's scroll position that corresponds to the desired target position.
      const desiredScrollX = scrollLeft - (desiredX - targetRect.left);
      const desiredScrollY = scrollTop - (desiredY - targetRect.top);

      vContainer.scrollTo({ top: desiredScrollY, behavior: "smooth" });
      hContainer.scrollTo({ left: desiredScrollX, behavior: "smooth" });
    };

    updateBounds();

    const hContainer = stepData.horizontalScrollContainerId
      ? document.getElementById(stepData.horizontalScrollContainerId)
      : window;
    const vContainer = stepData.verticalScrollContainerId
      ? document.getElementById(stepData.verticalScrollContainerId)
      : window;

    const updateTargetBoundsCb = () => {
      if (!stepData.selector) {
        return;
      }

      const el = document.querySelector(
        stepData.selector,
      ) as HTMLElement | null;
      if (!el) {
        return;
      }

      const updatedRect = el.getBoundingClientRect();
      setTargetBounds({
        x: updatedRect.left - PADDING,
        y: updatedRect.top - PADDING,
        width: updatedRect.width + PADDING * 2,
        height: updatedRect.height + PADDING * 2,
      });
    };

    updateTargetBoundsCb();
    hContainer?.addEventListener("scroll", updateTargetBoundsCb);
    vContainer?.addEventListener("scroll", updateTargetBoundsCb);
    window.addEventListener("resize", updateTargetBoundsCb);

    return () => {
      hContainer?.removeEventListener("scroll", updateTargetBoundsCb);
      vContainer?.removeEventListener("scroll", updateTargetBoundsCb);
      window.removeEventListener("resize", updateTargetBoundsCb);
    };
  }, [setTargetBounds, stepData]);
};
