import { type ParsedQs } from "qs";
import { useState, useCallback } from "react";
import {
  deleteQueryParam,
  getQueryParam,
  requireBoolean,
  requireNumber,
  updateQueryParam,
} from "../../../../rounds/query_param_utils";

export type TutorialStep = {
  content: React.ReactNode;
  selector?: string;
  /**
   * Callback to trigger after user clicks the "Next step" button but before actually advancing the step.
   */
  afterCb?: () => void;
  /**
   * Callback to trigger after user clicks the "Previous step" button but before actually going back to the previous step.
   */
  prevCb?: () => void;
  horizontalScrollContainerId?: string;
  verticalScrollContainerId?: string;
};

const TUTORIAL_QUERY_KEYS = {
  IS_OPEN: "tutorial",
  STEP: "tutorialStep",
};

export const useTutorial = (
  steps: TutorialStep[],
  queryParams: ParsedQs | URLSearchParams | undefined,
) => {
  const [tutorialOpen, setTutorialOpen] = useState(
    queryParams
      ? requireBoolean(getQueryParam(queryParams, TUTORIAL_QUERY_KEYS.IS_OPEN))
      : false,
  );
  const [currentStep, setCurrentStep] = useState(
    queryParams
      ? (requireNumber(getQueryParam(queryParams, TUTORIAL_QUERY_KEYS.STEP)) ??
          0)
      : 0,
  );

  const startTutorial = useCallback(() => {
    setTutorialOpen(true);
    setCurrentStep(0);
    updateQueryParam(TUTORIAL_QUERY_KEYS.STEP, "0");
    updateQueryParam(TUTORIAL_QUERY_KEYS.IS_OPEN, "true");
  }, []);

  const closeTutorial = useCallback(() => {
    setTutorialOpen(false);
    setCurrentStep(0);
    deleteQueryParam(TUTORIAL_QUERY_KEYS.STEP);
    deleteQueryParam(TUTORIAL_QUERY_KEYS.IS_OPEN);
  }, []);

  const goToNextStep = useCallback(() => {
    if (currentStep === steps.length - 1) {
      closeTutorial();
    } else {
      setCurrentStep((prevStep) => {
        updateQueryParam(TUTORIAL_QUERY_KEYS.STEP, (prevStep + 1).toString());
        return prevStep + 1;
      });
    }
  }, [closeTutorial, currentStep, steps.length]);

  const goToPreviousStep = useCallback(() => {
    if (currentStep > 0) {
      setCurrentStep((prevStep) => {
        updateQueryParam(TUTORIAL_QUERY_KEYS.STEP, (prevStep - 1).toString());
        return prevStep - 1;
      });
    }
  }, [currentStep]);

  return {
    isTutorialOpen: tutorialOpen,
    currentStep,
    startTutorial,
    closeTutorial,
    goToNextStep,
    goToPreviousStep,
  };
};
